	router.PUT("/k8s/cluster/:id/namespaces/:namespaceName/deployments/:deploymentName", middleware.AuthMiddleware(), k8sWorkloadCtrl.UpdateDeployment)
	router.DELETE("/k8s/cluster/:id/namespaces/:namespaceName/deployments/:deploymentName", middleware.AuthMiddleware(), k8sWorkloadCtrl.DeleteDeployment)
	router.POST("/k8s/cluster/:id/namespaces/:namespaceName/deployments/:deploymentName/scale", middleware.AuthMiddleware(), k8sWorkloadCtrl.ScaleDeployment)
	router.POST("/k8s/cluster/:id/namespaces/:namespaceName/deployments/:deploymentName/restart", middleware.AuthMiddleware(), k8sWorkloadCtrl.RestartDeployment)

	router.POST("/k8s/cluster/:id/namespaces/:namespaceName/statefulsets", middleware.AuthMiddleware(), k8sWorkloadCtrl.CreateStatefulSet)
	router.PUT("/k8s/cluster/:id/namespaces/:namespaceName/statefulsets/:statefulSetName", middleware.AuthMiddleware(), k8sWorkloadCtrl.UpdateStatefulSet)
	router.DELETE("/k8s/cluster/:id/namespaces/:namespaceName/statefulsets/:statefulSetName", middleware.AuthMiddleware(), k8sWorkloadCtrl.DeleteStatefulSet)
