	router.GET("/k8s/cluster/:id/namespaces/:namespaceName/services/:serviceName", middleware.AuthMiddleware(), k8sServiceCtrl.GetServiceDetail)
	router.POST("/k8s/cluster/:id/namespaces/:namespaceName/services", middleware.AuthMiddleware(), k8sServiceCtrl.CreateService)
