	router.DELETE("/k8s/cluster/:id/namespaces/:namespaceName/services/:serviceName", middleware.AuthMiddleware(), k8sServiceCtrl.DeleteService)
	router.GET("/k8s/cluster/:id/namespaces/:namespaceName/services/:serviceName/yaml", middleware.AuthMiddleware(), k8sServiceCtrl.GetServiceYaml)
	router.PUT("/k8s/cluster/:id/namespaces/:namespaceName/services/:serviceName/yaml", middleware.AuthMiddleware(), k8sServiceCtrl.UpdateServiceYaml)
	router.GET("/k8s/cluster/:id/namespaces/:namespaceName/services/:serviceName/events", middleware.AuthMiddleware(), k8sServiceCtrl.GetServiceEvents)

