	router.PUT("/k8s/cluster/:id/namespaces/:namespaceName/ingresses/:ingressName", middleware.AuthMiddleware(), k8sIngressCtrl.UpdateIngress)
	router.DELETE("/k8s/cluster/:id/namespaces/:namespaceName/ingresses/:ingressName", middleware.AuthMiddleware(), k8sIngressCtrl.DeleteIngress)
